# SALAH: tidak mengecil
def faktorial(n):
    if n <= 1:
        return 1
    return n * faktorial(n)      # n, bukan n - 1

# SALAH: kasus dasar tidak pernah tercapai
def mundur(n):
    if n == 0:
        return
    print(n)
    mundur(n - 2)                # dari 5 akan melewati 0 terus

def faktorial_ulang(n):
    hasil = 1
    for i in range(2, n + 1):
        hasil = hasil * i
    return hasil

print(faktorial_ulang(5))   # 120

# Menjumlahkan semua angka di daftar bersarang
def jumlah_semua(daftar):
    total = 0
    for x in daftar:
        if isinstance(x, list):
            total = total + jumlah_semua(x)   # cabang, panggil lagi
        else:
            total = total + x
    return total

print(jumlah_semua([1, [2, 3], [4, [5, 6]]]))   # 21

def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(30))   # benar, tapi lambat
